window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-12391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκεκάσμην</h1><div class=\"entry-meta\"><span>DGP · ordem 1152 na letra ε · nº geral 12391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καίνυμαι.</p></section></article>\n<article id=\"entry-dgp-12392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκέκλετο</h1><div class=\"entry-meta\"><span>DGP · ordem 1153 na letra ε · nº geral 12392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κέλομαι.</p></section></article>\n<article id=\"entry-dgp-12393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκεκράγετε</h1><div class=\"entry-meta\"><span>DGP · ordem 1154 na letra ε · nº geral 12393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª pl. m.-q.-perf. de κράζω.</p></section></article>\n<article id=\"entry-dgp-12394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκέρασα</h1><div class=\"entry-meta\"><span>DGP · ordem 1155 na letra ε · nº geral 12394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κεράννυμι.</p></section></article>\n<article id=\"entry-dgp-12395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκέρδησα</h1><div class=\"entry-meta\"><span>DGP · ordem 1156 na letra ε · nº geral 12395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. jôn. de κερδαίνω.</p></section></article>\n<article id=\"entry-dgp-12396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκερσα</h1><div class=\"entry-meta\"><span>DGP · ordem 1157 na letra ε · nº geral 12396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ép. de κείρω.</p></section></article>\n<article id=\"entry-dgp-12397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκεχειρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1158 na letra ε · nº geral 12397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 suspensão de armas; trégua; armistício 2 repouso; suspensão de trabalho 3 abstinência; contenção 4 permissão; licença para realizar um ato. 〈ἔχω, χείρ〉</p></section></article>\n<article id=\"entry-dgp-12398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκζέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1159 na letra ε · nº geral 12398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκζέσω) 1 fazer ferver 2 levantar fervura; ferver 3 fervilhar de, gen. ou dat., rar. ac. 4 arder; inflamar (de paixão) 5 pulular.</p></section></article>\n<article id=\"entry-dgp-12399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκζητέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1160 na letra ε · nº geral 12399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. 1 procurar; buscar; pesquisar a respeito de, περί e gen. 2 pedir contas de; cobrar satisfação de, ac. 3 requerer 4 seguir: ἐκζ. τὸν θεόν sept. ser seguidor da divindade, honrar a divindade 5 seguir fielmente algo, ac.</p></section></article>\n<article id=\"entry-dgp-12400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκζήτησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1161 na letra ε · nº geral 12400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crist. pesquisa profunda; busca perseverante. 〈ἐκζητέω〉</p></section></article>\n<article id=\"entry-dgp-12401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκζωπυρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1162 na letra ε · nº geral 12401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 reacender 2 reanimar; renovar.</p></section></article>\n<article id=\"entry-dgp-12402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκζωπύρησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1163 na letra ε · nº geral 12402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de reanimar, de reavivar. 〈ἐκζωπυρέω〉</p></section></article>\n<article id=\"entry-dgp-12403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκηα</h1><div class=\"entry-meta\"><span>DGP · ordem 1164 na letra ε · nº geral 12403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ép. de καίω.</p></section></article>\n<article id=\"entry-dgp-12404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκηβολία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1165 na letra ε · nº geral 12404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de arremessar lanças ao longe 2 habilidade de lançar ao longe. 〈ἑκηβόλος〉</p></section></article>\n<article id=\"entry-dgp-12405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκηβόλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1166 na letra ε · nº geral 12405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hábil no arremesso (com arco) 2 que lança dardos ao longe; que atinge o alvo, epít. de Apolo, de Ártemis e de Zeus. 〈ἑκάς, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-12406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕκηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1167 na letra ε · nº geral 12406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calmo; tranqüilo; pacato 2 não trabalhado; em repouso (terra) ♦ ἕκηλα adv. 3 tranqüilamente.</p></section></article>\n<article id=\"entry-dgp-12407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕκητι</h1><div class=\"entry-meta\"><span>DGP · ordem 1168 na letra ε · nº geral 12407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = ἕκατι.</p></section></article>\n<article id=\"entry-dgp-12408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθαμβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1169 na letra ε · nº geral 12408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 ficar estarrecido; assombrar-se 2 assombrar; pasmar. 〈ἔκθαμβος〉</p></section></article>\n<article id=\"entry-dgp-12409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκθαμβος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1170 na letra ε · nº geral 12409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tomado de espanto; pasmado; perplexo 2 terrível.</p></section></article>\n<article id=\"entry-dgp-12410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθαμνίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1171 na letra ε · nº geral 12410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(subj. aor. 2ª pl. ἐκθαμνίσητε) extirpar. 〈ἐκ, θάμνος〉</p></section></article>\n<article id=\"entry-dgp-12411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκθανον</h1><div class=\"entry-meta\"><span>DGP · ordem 1172 na letra ε · nº geral 12411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 poét. de ἐκθνῄσκω.</p></section></article>\n<article id=\"entry-dgp-12412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθαρρέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1173 na letra ε · nº geral 12412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἐκθαρσέω-ῶ 1 ter plena confiança; estar confiante em algo, dat. 2 ser encorajado por alguém, ὑπό e gen.</p></section></article>\n<article id=\"entry-dgp-12413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθάρσημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1174 na letra ε · nº geral 12413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">motivo de confiança; confiança. 〈ἐκθαρρέω〉</p></section></article>\n<article id=\"entry-dgp-12414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθαυμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1175 na letra ε · nº geral 12414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. olhar com espanto; admirar, ac.</p></section></article>\n<article id=\"entry-dgp-12415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθεάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1176 na letra ε · nº geral 12415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. ἐκθεάσασθαι) 1 contemplar; observar ♦ pas. 2 tornar-se visível.</p></section></article>\n<article id=\"entry-dgp-12416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθειάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1177 na letra ε · nº geral 12416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tratar como divino; deificar; divinizar alguém 2 considerar alguém ou algo como divino.</p></section></article>\n<article id=\"entry-dgp-12417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθειόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1178 na letra ε · nº geral 12417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">elevar à condição dos deuses ou das coisas divinas; divinizar.</p></section></article>\n<article id=\"entry-dgp-12418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθεόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1179 na letra ε · nº geral 12418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 divinizar ♦ méd. 2 considerar-se ou declarar-se deus.</p></section></article>\n<article id=\"entry-dgp-12419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθεραπεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1180 na letra ε · nº geral 12419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cuidar bem 2 conquistar alguém graças a, dat. 3 sobrecarregar de cuidados ♦ méd. 4 cuidar-se.</p></section></article>\n<article id=\"entry-dgp-12420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθερμαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1181 na letra ε · nº geral 12420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquecer; esquentar 2 fazer evaporar pelo calor ♦ pas. 3 tornar-se quente; ser aquecido.</p></section></article>\n<article id=\"entry-dgp-12421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκθεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1182 na letra ε · nº geral 12421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exposição; mostra; exibição de algo 2 exposição (de criança); desembarque 3 exposição; explicação 4 aposta; cacife 5 Mús. série de notas musicais. 〈ἐκτίθημι〉</p></section></article>\n<article id=\"entry-dgp-12422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκθεσμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1183 na letra ε · nº geral 12422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ilegal; ilícito 2 monstruoso; extraordinário; anormal. 〈ἐκ, θεσμός〉</p></section></article>\n<article id=\"entry-dgp-12423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθετέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1184 na letra ε · nº geral 12423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἐκτίθημι.</p></section></article>\n<article id=\"entry-dgp-12424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκθετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1185 na letra ε · nº geral 12424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 afastado; apartado 2 abandonado; exposto. 〈ἐκτίθημι〉</p></section></article>\n<article id=\"entry-dgp-12425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1186 na letra ε · nº geral 12425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 correr para fora 2 sair correndo; sair voando; desaparecer.</p></section></article>\n<article id=\"entry-dgp-12426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθηράομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1187 na letra ε · nº geral 12426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caçar 2 capturar.</p></section></article>\n<article id=\"entry-dgp-12427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθηρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1188 na letra ε · nº geral 12427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκθηράομαι.</p></section></article>\n<article id=\"entry-dgp-12428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθλίβω</h1><div class=\"entry-meta\"><span>DGP · ordem 1189 na letra ε · nº geral 12428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espremer pressionando uma fruta 2 esmagar (tropas) 3 prensar (cabelo) para fixar ou alisar ♦ pas. 4 Gram., tard. (vogal) elidir; sofrer crase.</p></section></article>\n<article id=\"entry-dgp-12429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθνῄσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1190 na letra ε · nº geral 12429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκθανοῦμαι) 1 cair num estado semelhante à morte; desfalecer 2 perf. estar como morto 3 morrer de: ἐκθ. γέλῳ, ἐκθ. ὑπὸ γέλωτος morrer de rir, ἐκθ. ὑπὸ δέους morrer de medo, ἐκθ. ὑπ᾽ αἰδοῦς morrer de vergonha 3 morrer.</p></section></article>\n<article id=\"entry-dgp-12430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθοινάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1191 na letra ε · nº geral 12430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">regalar-se com; devorar.</p></section></article>\n<article id=\"entry-dgp-12431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθορεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1192 na letra ε · nº geral 12431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de ἐκθρῴσκω.</p></section></article>\n<article id=\"entry-dgp-12432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθόρνυμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1193 na letra ε · nº geral 12432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐκθρῴσκω.</p></section></article>\n<article id=\"entry-dgp-12433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκθρεψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1194 na letra ε · nº geral 12433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de criar; educação. 〈ἐκτρέφω〉</p></section></article>\n<article id=\"entry-dgp-12434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθρηνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1195 na letra ε · nº geral 12434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lamentar-se sobre, ac.</p></section></article>\n<article id=\"entry-dgp-12435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθρῴσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1196 na letra ε · nº geral 12435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκθοροῦμαι, aor.2 ἐξέθορον, perf. desus.) saltar; pular; lançar-se fora de, gen., rar. ac., ou ἀπό e gen.</p></section></article>\n<article id=\"entry-dgp-12436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκθυμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1197 na letra ε · nº geral 12436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">levado pela força do coração; impetuoso; ardoroso.</p></section></article>\n<article id=\"entry-dgp-12437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθύμως</h1><div class=\"entry-meta\"><span>DGP · ordem 1198 na letra ε · nº geral 12437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com ardor; impetuosamente.</p></section></article>\n<article id=\"entry-dgp-12438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθύσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1199 na letra ε · nº geral 12438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que precisa ser expiado; que merece expiação. 〈ἐκθύω〉</p></section></article>\n<article id=\"entry-dgp-12439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκθυσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1200 na letra ε · nº geral 12439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sacrifício expiatório. 〈ἐκθύω〉</p></section></article>\n<article id=\"entry-dgp-12440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκθύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1201 na letra ε · nº geral 12440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sacrificar; imolar ♦ méd. 2 oferecer sacrifícios de expiação a um deus, dat. 3 expiar por algo ou alguém, ὑπέρ e gen. 4 expiar algo, ac. 5 apaziguar; aplacar alguém, ac. 6 afastar algo, ac., por meio de expiação.</p></section></article>\n<article id=\"entry-dgp-12441\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκίνηθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1202 na letra ε · nº geral 12441</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. pas. ép. de κινέω.</p></section></article>\n<article id=\"entry-dgp-12442\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκιον</h1><div class=\"entry-meta\"><span>DGP · ordem 1203 na letra ε · nº geral 12442</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κίω.</p></section></article>\n<article id=\"entry-dgp-12443\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκιχον</h1><div class=\"entry-meta\"><span>DGP · ordem 1204 na letra ε · nº geral 12443</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κιχάνω.</p></section></article>\n<article id=\"entry-dgp-12444\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαγχάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1205 na letra ε · nº geral 12444</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arrebentar de rir.</p></section></article>\n<article id=\"entry-dgp-12445\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαθαίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1206 na letra ε · nº geral 12445</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐκκάθηρα) 1 tornar puro; limpar; purificar: χθόνα τήνδ᾽ ἐκκαθαίρει κνωδάλων βροτοφθόρων ésql. [Ápis] purifica esta terra, de monstros que fazem perecer os mortais 2 depurar 3 fazer desaparecer algo, ac., por purificação; purificar de; redimir de.</p></section></article>\n<article id=\"entry-dgp-12446\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαθεύδω</h1><div class=\"entry-meta\"><span>DGP · ordem 1207 na letra ε · nº geral 12446</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐξεκάθευδον) passar a noite fora a velar.</p></section></article>\n<article id=\"entry-dgp-12447\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκάθηρα</h1><div class=\"entry-meta\"><span>DGP · ordem 1208 na letra ε · nº geral 12447</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐκκαθαίρω.</p></section></article>\n<article id=\"entry-dgp-12448\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκκαίδεκα</h1><div class=\"entry-meta\"><span>DGP · ordem 1209 na letra ε · nº geral 12448</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. card. indecl. dezesseis.</p></section></article>\n<article id=\"entry-dgp-12449\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκκαιδεκάδωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1210 na letra ε · nº geral 12449</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do comprimento de dezesseis palmos. 〈ἑκκαίδεκα, δῶρον〉</p></section></article>\n<article id=\"entry-dgp-12450\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκκαιδεκαετής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1211 na letra ε · nº geral 12450</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἐκκαιδεκαέτης, ης, ες 1 com a idade de dezesseis anos 2 com duração de dezesseis anos. 〈ἑκκαίδεκα, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-12451\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκκαιδεκάπηχυς, υς, υ</h1><div class=\"entry-meta\"><span>DGP · ordem 1212 na letra ε · nº geral 12451</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. εος-ους de dezesseis côvados. 〈ἑκκαίδεκα, πῆχυς〉</p></section></article>\n<article id=\"entry-dgp-12452\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκκαιδεκέτης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1213 na letra ε · nº geral 12452</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com a idade de dezesseis anos. 〈ἑκκαίδεκα, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-12453\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκκαιδεκήρης, εος-ους (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1214 na letra ε · nº geral 12453</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barco de dezesseis filas de remadores. 〈ἑκκαίδεκα, ἀραρίσκω〉</p></section></article>\n<article id=\"entry-dgp-12454\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαίω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1215 na letra ε · nº geral 12454</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ἐκκάω (impf. ἐξέκαιον, át. ἐξέκαον, fut. ἐκκαύσω, aor. ἐξέκηα, aor. rec. ἐξέκαυσα, perf. desus.; pas. fut. ἐκκαυθήσομαι, aor.1 ἐξεκαύθην, aor.2 ἐξεκάην, perf. ἐκκέκαυμαι) 1 queimar 2 acender 3 inflamar; excitar; estimular 4 ressecar; secar ♦ pas. 5 queimar-se; inflamar-se; arder 6 perf. estar inflamado.</p></section></article>\n<article id=\"entry-dgp-12455\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκακέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1216 na letra ε · nº geral 12455</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 perder a coragem; ceder ao desânimo; desanimar 2 agir com displicência.</p></section></article>\n<article id=\"entry-dgp-12456\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1217 na letra ε · nº geral 12456</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 chamar para fora 2 chamar; atrair; provocar 3 invocar ♦ méd. 4 chamar a si ou para si; evocar; invocar para si 5 convidar alguém, ac., para algo, πρός e ac., ou para fazer algo, inf. 6 provocar; excitar algo ou alguém 7 protestar contra algo, ac., junto a alguém, ἐπί e ac.</p></section></article>\n<article id=\"entry-dgp-12457\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκάλυμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1218 na letra ε · nº geral 12457</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">meio de fazer descobrir; indício; sinal. 〈ἐκκαλύπτω〉</p></section></article>\n<article id=\"entry-dgp-12458\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαλύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1219 na letra ε · nº geral 12458</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tirar a coberta de; descobrir 2 revelar 3 explicar 4 desmascarar ♦ méd. 5 descobrir-se; descobrir o rosto.</p></section></article>\n<article id=\"entry-dgp-12459\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκάμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1220 na letra ε · nº geral 12459</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐξέκαμνον, fut. ἐκκαμοῦμαι, aor.2 ἐξέ­καμον) 1 fatigar-se de; cansar-se de, ac. 2 tornar-se fraco para algo, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-12460\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαρπίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1221 na letra ε · nº geral 12460</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar como fruto; frutificar; produzir 2 exaurir pela produção uma terra.</p></section></article>\n<article id=\"entry-dgp-12461\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαρπόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1222 na letra ε · nº geral 12461</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκκαρπώσομαι) 1 ter como fruto; produzir 2 usufruir 3 aproveitar-se de; tirar proveito de alguém ou algo, ac.</p></section></article>\n<article id=\"entry-dgp-12462\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαταπάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1223 na letra ε · nº geral 12462</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 pas. 3ª sing. ἐκκατέπαλτο) lançar-se de, gen.</p></section></article>\n<article id=\"entry-dgp-12463\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκατιδών</h1><div class=\"entry-meta\"><span>DGP · ordem 1224 na letra ε · nº geral 12463</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. at. nom. masc. sing. olhando do alto de, gen. 〈ἐκ, κατά, ἰδών〉</p></section></article>\n<article id=\"entry-dgp-12464\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκαυστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1225 na letra ε · nº geral 12464</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para queimar; inflamável. 〈ἐκκαίω〉</p></section></article>\n<article id=\"entry-dgp-12465\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκάω</h1><div class=\"entry-meta\"><span>DGP · ordem 1226 na letra ε · nº geral 12465</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = ἐκκαίω.</p></section></article>\n<article id=\"entry-dgp-12466\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκκειμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1227 na letra ε · nº geral 12466</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκκείσομαι) 1 estar estendido fora; estar abandonado ou exposto 2 estender-se fora; sair fora de, gen. 3 (promontório, muro) estar saliente; apresentar relevo 4 estender-se à vista de todos; estar exposto ao público; (decreto, aviso) estar afixado 5 estar exposto; ser narrado, para o conhecimento de todos 6 (finalidade, recompensa) ser proposto 7 estar à disposição de; estar à mercê de, dat.</p></section></article>\n<article id=\"entry-dgp-12467\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκεινόω</h1><div class=\"entry-meta\"><span>DGP · ordem 1228 na letra ε · nº geral 12467</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐκκενόω.</p></section></article>\n<article id=\"entry-dgp-12468\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκενόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1229 na letra ε · nº geral 12468</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar vazio; tornar deserto; esvaziar; despovoar; evacuar 2 verter até o fim; exaurir; esgotar 3 tirar da bainha; desembainhar ♦ pas. 4 tornar-se vazio; esvaziar-se; tornar-se deserto.</p></section></article>\n<article id=\"entry-dgp-12469\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκεντέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1230 na letra ε · nº geral 12469</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐξεκέντησα) 1 tirar de dentro espetando 2 transpassar; ferir: ἐκκ. τὰ ὄμματα artt. furar os olhos 3 massacrar.</p></section></article>\n<article id=\"entry-dgp-12470\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκεχυμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 1231 na letra ε · nº geral 12470</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em profusão; com abundância 2 com efusividade. 〈ἐκχέω〉</p></section></article>\n<article id=\"entry-dgp-12471\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκηραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1232 na letra ε · nº geral 12471</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª pl. ἐξεκήραναν) enfraquecer; esgotar.</p></section></article>\n<article id=\"entry-dgp-12472\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκηρύσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1233 na letra ε · nº geral 12472</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ύττω 1 proclamar pela voz do arauto 2 expulsar com proclama ou banir pela voz do arauto: ἀλλ᾽ ἀνάστατος αὐτοῖν ἐπέμφθην κἀξεκηρύχθην φυγάς sóf. mas, despojado do que era meu e por eles expulso, anunciou-se meu exílio.</p></section></article>\n<article id=\"entry-dgp-12473\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1234 na letra ε · nº geral 12473</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pôr em movimento para fazer sair; fazer erguer-se 2 deixar escapar (palavra) 3 provocar; suscitar; reavivar (dor, doença) ♦ pas. 4 ser colocado fora de si; ser perturbado.</p></section></article>\n<article id=\"entry-dgp-12474\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1235 na letra ε · nº geral 12474</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 romper 2 destroçar ♦ pas. 3 estar destroçado; estar enfraquecido.</p></section></article>\n<article id=\"entry-dgp-12475\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλείω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1236 na letra ε · nº geral 12475</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ἐκκληΐω, át. ant. ἐκκλῄω 1 manter alguém, ac., afastado de, gen.; excluir 2 impedir; interditar algo, ac.; impedir de, inf. 3 cortar; interromper.</p></section></article>\n<article id=\"entry-dgp-12476\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλέπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1237 na letra ε · nº geral 12476</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκκλέψω, aor.2 pas. ἐξεκλάπην etc.) 1 roubar; raptar alguém, ac., de, gen. ou ἐκ e gen. 2 subtrair alguém, ac., de algo, gen. ou ἐκ e gen. ou com μή e inf. 3 suprimir algo, ac., de, gen. 4 dissimular (discurso, casamento) 5 enganar alguém.</p></section></article>\n<article id=\"entry-dgp-12477\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκληΐω</h1><div class=\"entry-meta\"><span>DGP · ordem 1238 na letra ε · nº geral 12477</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐκκλείω.</p></section></article>\n<article id=\"entry-dgp-12478\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλησία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1239 na letra ε · nº geral 12478</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assembléia por convocação; reunião: ἐκκλησίαν συλλέγειν, ἀθροίζειν, συνάγειν, συναγείρειν reunir uma assembléia, ἐκκλησίαν διαλύειν, ἀναστῆσαι, ἀφιέναι dissolver uma assembléia, ἐκκλησίαν ἀναβάλλειν adiar uma assembléia 2 assembléia do povo, de soldados 3 bíbl. a comunidade; Igreja 4 bíbl. lugar de reunião; igreja. 〈ἐκκαλέω〉</p></section></article>\n<article id=\"entry-dgp-12479\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλησιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1240 na letra ε · nº geral 12479</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐξεκλησίαζον e ἠκκλησίαζον) 1 realizar sessão de assembléia 2 discutir em reunião; deliberar 3 participar dos trabalhos de assembléia; ser membro de assembléia 4 convocar uma assembléia; reunir ♦ méd. 5 bíbl. freqüentar a Igreja. 〈ἐκκλησία〉</p></section></article>\n<article id=\"entry-dgp-12480\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλησιαστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1241 na letra ε · nº geral 12480</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 membro de assembléia 2 cidadão que toma parte nas deliberações de assembléia 3 orador da assembléia. 〈ἐκκλησιάζω〉</p></section></article>\n<article id=\"entry-dgp-12481\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλησιαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1242 na letra ε · nº geral 12481</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da assembléia do povo; ἐκκλη­σιαστικὸς πίναξ lista dos cidadãos inscritos para a assembléia 2 crist. da Igreja; eclesiástico; clerical ♦ τὸ ἐκκλησιαστικόν 3 remuneração dada aos membros da assembléia do povo por sessão a que comparecem. 〈ἐκκλησιάζω〉</p></section></article>\n<article id=\"entry-dgp-12482\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκκλησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1243 na letra ε · nº geral 12482</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apelo 2 invocação de divindade. 〈ἐκκαλέω〉</p></section></article>\n<article id=\"entry-dgp-12483\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλητεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1244 na letra ε · nº geral 12483</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">intimar testemunha que não compareceu e está, pois, sujeita à multa. 〈ἔκκλητος〉</p></section></article>\n<article id=\"entry-dgp-12484\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκκλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1245 na letra ε · nº geral 12484</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escolhido ou designado como árbitro 2 designado como membro de assembléia: ἔκκλητος ὄχλος eur. multidão designada para a assembléia; assembléia 3 Jur. de que se pode apelar; que admite recurso (processo) ♦ οἱ ἔκκλητοι 4 membros designados para a assembléia; assembléia ♦ ἡ ἔκκλητος 5 assembléia por convocação. 〈ἐκκαλέω〉</p></section></article>\n<article id=\"entry-dgp-12485\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλῄω</h1><div class=\"entry-meta\"><span>DGP · ordem 1246 na letra ε · nº geral 12485</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = ἐκκλείω.</p></section></article>\n<article id=\"entry-dgp-12486\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1247 na letra ε · nº geral 12486</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer flexionar; fazer desviar 2 alterar; declinar (nome) 3 desviar-se; afastar-se de algo, ἐκ e gen., de alguém, ἀπό e gen. 4 dobrar 5 ceder; recuar 6 inclinar-se para, εἰς e ac. 7 evitar.</p></section></article>\n<article id=\"entry-dgp-12487\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκκλισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1248 na letra ε · nº geral 12487</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desvio; deslocamento; declinação (astro) 2 inclinação; tendência 3 ação de evitar; recusa de, gen. 4 afastamento (moral) 5 Medic. luxação; deslocamento. 〈ἐκκλίνω〉</p></section></article>\n<article id=\"entry-dgp-12488\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλιτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1249 na letra ε · nº geral 12488</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἐκκλίνω.</p></section></article>\n<article id=\"entry-dgp-12489\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκκλύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1250 na letra ε · nº geral 12489</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lavar; limpar bem 2 tard. transbordar ♦ méd. 3 lavar-se.</p></section></article>\n<article id=\"entry-dgp-12490\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκκλυσμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1251 na letra ε · nº geral 12490</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ablução; lavagem. 〈ἐκκλύζω〉</p></section></article>\n";
